describe('Store.listShipments on a large dataset (5k shipments)', () => {
  it('returns the newest shipments first, respects limit and filters, and stays fast', () => {
    const store = new Store();
    const base = Date.parse('2026-01-01T00:00:00Z');
    for (let i = 0; i < 5000; i++) {
      // inserted oldest -> newest, alternating carriers
      store.addShipment({ ...input(i), carrier: i % 2 ? 'DHL' : 'UPS' }, new Date(base + i * 60_000));
    }

    const started = performance.now();
    const top = store.listShipments({ limit: 50 });
    const elapsed = performance.now() - started;

    assert.equal(top.length, 50);
    assert.equal(top[0].trackingNumber, 'T4999');
    assert.equal(top[49].trackingNumber, 'T4950');
    for (let i = 1; i < top.length; i++) assert.ok(top[i - 1].createdAt > top[i].createdAt);

    const ups = store.listShipments({ carrier: 'UPS', limit: 3 });
    assert.deepEqual(ups.map((s) => s.trackingNumber), ['T4998', 'T4996', 'T4994']);

    // Very generous bound (typically < 5 ms) - only catches a gross regression, not machine noise.
    assert.ok(elapsed < 250, `listing took ${elapsed.toFixed(1)} ms`);
  });
});
EOF
